import numpy as np
from numba import njit

@njit
def lapjv(cost):
    """Jonker-Volgenant algorithm for the linear assignment problem.
    Minimizes sum cost[i, col[i]]. Returns col assignment (int64 array of length n).
    cost must be float64 2d contiguous, square.
    """
    n = cost.shape[0]
    INF = 1.0e18

    u = np.zeros(n, dtype=np.float64)
    v = np.zeros(n, dtype=np.float64)
    rowsol = np.full(n, -1, dtype=np.int64)
    colsol = np.full(n, -1, dtype=np.int64)

