    for j in range(n - 1, -1, -1):
        minv = cost[0, j] - u[0]
        mini = 0
        for i in range(1, n):
            val = cost[i, j] - u[i]
            if val < minv:
                minv = val
                mini = i
        v[j] = minv
        if rowsol[mini] == -1:
            rowsol[mini] = j
            colsol[j] = mini

    # REDUCTION TRANSFER
    for i in range(n):
        if rowsol[i] == -1:
            continue
        j1 = rowsol[i]
        minv = INF
        for j in range(n):
            if j == j1:
                continue
            val = cost[i, j] - v[j]
            if val < minv:
                minv = val
        v[j1] = cost[i, j1] - minv

    # AUGMENTING ROW REDUCTION
    for _pass in range(2):
        for i in range(n):
            if rowsol[i] != -1:
                continue
            u1 = INF
            u2 = INF
            j1 = -1
            for j in range(n):
                h = cost[i, j] - v[j]
                if h < u2:
                    if h >= u1:
                        u2 = h
                    else:
                        u2 = u1
                        u1 = h
                        j1 = j
            i0 = colsol[j1]
            if u1 < u2:
                v[j1] = v[j1] - (u2 - u1)
            else:
                if i0 != -1:
                    continue
            if i0 != -1:
                rowsol[i0] = -1
            colsol[j1] = i
            rowsol[i] = j1

    # AUGMENTATION
    pred = np.empty(n, dtype=np.int64)
    free = np.empty(n, dtype=np.int64)
    nfree = 0
    for i in range(n):
        if rowsol[i] == -1:
            free[nfree] = i
            nfree += 1

    col_list = np.empty(n, dtype=np.int64)
    d = np.empty(n, dtype=np.float64)

    for f in range(nfree):
        freerow = free[f]
        for j in range(n):
            d[j] = cost[freerow, j] - v[j]
            pred[j] = freerow
        scanned = np.zeros(n, dtype=np.uint8)
        low = 0
        up = 0
        minv = INF
        endcol = -1
        for j in range(n):
            if d[j] < minv:
                minv = d[j]
        for j in range(n):
            if d[j] == minv:
                if colsol[j] == -1:
                    endcol = j
                    break
                col_list[up] = j
                up += 1
                scanned[j] = 1
        if endcol == -1:
            while True:
                if low == up:
                    minv2 = INF
                    for j in range(n):
                        if scanned[j] == 0 and d[j] < minv2:
                            minv2 = d[j]
                    delta = minv2 - minv
                    for j in range(n):
                        if scanned[j]:
                            v[j] += delta
                            irow = colsol[j]
                            u[irow] -= delta
                        else:
                            d[j] -= delta
                    minv = minv2
                    for j in range(n):
                        if scanned[j] == 0 and d[j] == 0.0:
                            if colsol[j] == -1:
