"""Jonker-Volgenant LAP solver, translated from the public-domain C implementation
commonly known as lapjv (Jonker & Volgenant, 1987), adapted to Numba.
"""
import numpy as np
from numba import njit

@njit
def _column_reduction(cost, u, v, rowsol, colsol, n):
    for j in range(n - 1, -1, -1):
        minv = cost[0, j]
        imin = 0
        for i in range(1, n):
            h = cost[i, j]
            if h < minv:
                minv = h
                imin = i
        v[j] = minv
        if rowsol[imin] == -1:
            rowsol[imin] = j
            colsol[j] = imin
        else:
            # this column not assigned; leave colsol[j] = -1
            pass

@njit
def _reduction_transfer(cost, u, v, rowsol, colsol, n):
    for i in range(n):
        if rowsol[i] == -1:
            continue
        j1 = rowsol[i]
        minv = 1.0e300
        for j in range(n):
            if j == j1:
                continue
            h = cost[i, j] - v[j]
            if h < minv:
                minv = h
        v[j1] = cost[i, j1] - minv
        u[i] = minv  # not always used

@njit
def _augmenting_row_reduction(cost, u, v, rowsol, colsol, n, passes=2):
    for _p in range(passes):
        for i in range(n):
            if rowsol[i] != -1:
                continue
            # find two smallest reduced costs
            u1 = 1.0e300
            u2 = 1.0e300
            j1 = -1
            j2 = -1
            for j in range(n):
                h = cost[i, j] - v[j]
                if h < u2:
                    if h >= u1:
                        u2 = h
                        j2 = j
                    else:
                        u2 = u1
                        j2 = j1
                        u1 = h
                        j1 = j
            i0 = colsol[j1]
            if u1 < u2:
                v[j1] -= (u2 - u1)
            else:
                # not unique; only assign if free
                if i0 != -1:
                    j1 = j2
                    i0 = colsol[j1]
                    if i0 != -1:
                        continue
            if i0 != -1:
                rowsol[i0] = -1
            rowsol[i] = j1
            colsol[j1] = i
            u[i] = u1

@njit
def _augment(cost, u, v, rowsol, colsol, n):
    """Shortest augmenting path for each free row. Dense Dijkstra with duals."""
    pred = np.empty(n, dtype=np.int64)
    d = np.empty(n, dtype=np.float64)
    scanned = np.empty(n, dtype=np.uint8)
    cols = np.empty(n, dtype=np.int64)

    for freerow in range(n):
        if rowsol[freerow] != -1:
            continue
        for j in range(n):
            d[j] = cost[freerow, j] - v[j]
            pred[j] = freerow
            scanned[j] = 0
        low = 0
        up = 0
        # current minimum among all (initially)
        minv = d[0]
        for j in range(1, n):
            if d[j] < minv:
                minv = d[j]
        endcol = -1
        for j in range(n):
            if d[j] == minv:
                if colsol[j] == -1:
                    endcol = j
                    break
                scanned[j] = 1
                cols[up] = j
                up += 1
        last_delta_base = minv
        if endcol == -1:
            while True:
                if low == up:
                    # raise duals
                    minv2 = 1.0e300
                    for j in range(n):
                        if scanned[j] == 0 and d[j] < minv2:
                            minv2 = d[j]
                    delta = minv2 - minv
                    for j in range(n):
                        if scanned[j]:
                            v[j] += delta
                            ir = colsol[j]
                            u[ir] -= delta
                        else:
                            d[j] -= delta
                    u[freerow] += delta
                    minv = minv2
                    for j in range(n):
                        if scanned[j] == 0 and d[j] <= 1e-15:
                            if colsol[j] == -1:
                                endcol = j
                                break
                            scanned[j] = 1
                            cols[up] = j
                            up += 1
                    if endcol != -1:
                        break
                    continue
                jcur = cols[low]
                low += 1
                irow = colsol[jcur]
                # reduced cost of matched edge ~ 0; use cost - v as reference
                # After dual updates, d values of unscanned are shifted.
                # The reduced cost from irow to j relative to matched edge:
                cred = cost[irow, jcur] - v[jcur]
                for j in range(n):
                    if scanned[j]:
                        continue
                    h = cost[irow, j] - v[j] - cred
                    if h < d[j]:
                        d[j] = h
                        pred[j] = irow
                        if h <= 1e-15:
                            if colsol[j] == -1:
                                endcol = j
                                break
                            scanned[j] = 1
                            cols[up] = j
                            up += 1
                if endcol != -1:
                    break
        # augment
        j = endcol
        while True:
            irow = pred[j]
            nxt = rowsol[irow]
            colsol[j] = irow
            rowsol[irow] = j
            if irow == freerow:
                break
            j = nxt

@njit
def lapjv(cost):
    n = cost.shape[0]
    u = np.zeros(n, dtype=np.float64)
    v = np.zeros(n, dtype=np.float64)
    rowsol = np.full(n, -1, dtype=np.int64)
    colsol = np.full(n, -1, dtype=np.int64)
    _column_reduction(cost, u, v, rowsol, colsol, n)
    _reduction_transfer(cost, u, v, rowsol, colsol, n)
    _augmenting_row_reduction(cost, u, v, rowsol, colsol, n, 2)
    _augment(cost, u, v, rowsol, colsol, n)
    return rowsol

def test():
    import time
    from scipy.optimize import linear_sum_assignment
    rng = np.random.default_rng(0)
    lapjv(rng.random((4,4)))
    fails = 0
    for trial in range(30):
        n = int(rng.integers(2, 25))
        C = rng.random((n, n))
        a = lapjv(C)
        _, c = linear_sum_assignment(C)
        diff = abs(C[np.arange(n), a].sum() - C[np.arange(n), c].sum())
        ok = len(set(a.tolist())) == n and diff < 1e-6
        if not ok:
            fails += 1
            print("fail", n, diff)
            if fails > 3:
                break
    print("fails", fails)
    for n in [100, 200, 400, 600]:
        C = rng.random((n, n))
        t0 = time.perf_counter(); a = lapjv(C); t1 = time.perf_counter()
        if n <= 200:
            t2 = time.perf_counter(); _, c = linear_sum_assignment(C); t3 = time.perf_counter()
            diff = abs(C[np.arange(n), a].sum() - C[np.arange(n), c].sum())
            print(n, "jv", round(t1-t0,4), "scipy", round(t3-t2,4), "diff", diff)
        else:
            print(n, "jv", round(t1-t0,4))

if __name__ == "__main__":
    test()
