/* Jonker-Volgenant LAP, adapted from the public-domain lap.h implementation
   (Jonker & Volgenant 1987), dense square minimization, float64 costs.
   assign[i] = column matched to row i.
*/
#include <stdlib.h>
#include <string.h>
#include <float.h>
#include <stdio.h>

#define BIG 1e18

static int lapjv(const double *cost, int n, int *rowsol) {
    int dim = n;
    int *colsol = (int *)malloc(n * sizeof(int));
    double *u = (double *)calloc(n, sizeof(double));
    double *v = (double *)calloc(n, sizeof(double));
    double *d = (double *)malloc(n * sizeof(double));
    int *pred = (int *)malloc(n * sizeof(int));
    int *free_rows = (int *)malloc(n * sizeof(int));
    char *collist_scanned = NULL;
    int *col = (int *)malloc(n * sizeof(int)); /* columns in the shortest path tree */
    if (!colsol || !u || !v || !d || !pred || !free_rows || !col) return 1;
    for (int i = 0; i < n; i++) { rowsol[i] = -1; colsol[i] = -1; }

    /* COLUMN REDUCTION */
    for (int j = n - 1; j >= 0; j--) {
        double minv = cost[j];
        int imin = 0;
        for (int i = 1; i < n; i++) {
            double h = cost[(size_t)i * n + j];
            if (h < minv) { minv = h; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] < 0) {
            rowsol[imin] = j;
            colsol[j] = imin;
        }
    }

    /* REDUCTION TRANSFER */
    for (int i = 0; i < n; i++) {
        if (rowsol[i] < 0) continue;
        int j1 = rowsol[i];
        double minv = BIG;
        const double *row = cost + (size_t)i * n;
        for (int j = 0; j < n; j++) {
            if (j == j1) continue;
            double h = row[j] - v[j];
            if (h < minv) minv = h;
        }
        v[j1] = row[j1] - minv;
    }

    /* AUGMENTING ROW REDUCTION */
    int nfree = 0;
    for (int loop = 0; loop < 2; loop++) {
        nfree = 0;
        for (int i = 0; i < n; i++) {
            if (rowsol[i] >= 0) continue;
            double u1 = BIG, u2 = BIG;
            int j1 = -1, j2 = -1;
            const double *row = cost + (size_t)i * n;
            for (int j = 0; j < n; j++) {
                double h = row[j] - v[j];
                if (h < u2) {
                    if (h >= u1) { u2 = h; j2 = j; }
                    else { u2 = u1; u1 = h; j2 = j1; j1 = j; }
                }
            }
            int i0 = colsol[j1];
            if (u1 < u2) {
                v[j1] -= (u2 - u1);
            } else if (i0 >= 0) {
                j1 = j2;
                i0 = colsol[j1];
            }
            if (i0 >= 0) {
                if (u1 < u2) {
                    rowsol[i0] = -1;
                    free_rows[nfree++] = i0;
                } else {
                    free_rows[nfree++] = i;
                    continue;
                }
            }
            rowsol[i] = j1;
            colsol[j1] = i;
        }
    }

    /* AUGMENTATION for remaining free rows */
    char *scanned = (char *)malloc(n);
    for (int f = 0; f < nfree; f++) {
        int freerow = free_rows[f];
        const double *frow = cost + (size_t)freerow * n;
        for (int j = 0; j < n; j++) {
            d[j] = frow[j] - v[j];
            pred[j] = freerow;
            scanned[j] = 0;
        }
        int low = 0, up = 0;
        double minv = d[0];
        for (int j = 1; j < n; j++) if (d[j] < minv) minv = d[j];
        int endcol = -1;
        for (int j = 0; j < n; j++) {
            if (d[j] <= minv + 1e-15) {
                if (colsol[j] < 0) { endcol = j; break; }
                scanned[j] = 1;
                col[up++] = j;
            }
        }
        if (endcol < 0) {
            while (1) {
                if (low == up) {
                    double minv2 = BIG;
                    for (int j = 0; j < n; j++) if (!scanned[j] && d[j] < minv2) minv2 = d[j];
                    double delta = minv2 - minv;
                    for (int j = 0; j < n; j++) {
                        if (scanned[j]) {
                            int irow = colsol[j];
                            v[j] += delta;
                            u[irow] -= delta;
                        } else {
                            d[j] -= delta;
                        }
                    }
                    minv = minv2;
                    for (int j = 0; j < n; j++) {
                        if (!scanned[j] && d[j] <= 1e-12) {
                            if (colsol[j] < 0) { endcol = j; break; }
                            scanned[j] = 1;
                            col[up++] = j;
                        }
                    }
                    if (endcol >= 0) break;
                    continue;
                }
                int jcur = col[low++];
                int irow = colsol[jcur];
                const double *row = cost + (size_t)irow * n;
                double cred = row[jcur] - v[jcur];
                for (int j = 0; j < n; j++) {
                    if (scanned[j]) continue;
                    double h = row[j] - v[j] - cred;
                    if (h < d[j]) {
                        d[j] = h;
                        pred[j] = irow;
                        if (h <= 1e-12) {
                            if (colsol[j] < 0) { endcol = j; break; }
                            scanned[j] = 1;
                            col[up++] = j;
                        }
                    }
                }
                if (endcol >= 0) break;
            }
        }
        /* augment */
        int j = endcol;
        while (1) {
            int irow = pred[j];
            int next = rowsol[irow];
            colsol[j] = irow;
            rowsol[irow] = j;
            if (irow == freerow) break;
            j = next;
        }
    }
    free(colsol); free(u); free(v); free(d); free(pred); free(free_rows); free(col); free(scanned);
    return 0;
}

/* exported */
int solve_lap(const double *cost, int n, int *assign) {
    return lapjv(cost, n, assign);
}
