#include <string.h>
#include <math.h>

/* Dense epsilon-scaling auction for assignment (minimization).
   Returns 0 and fills assign[i] = column.
   Not always the same optimal plan as network simplex when there are ties,
   but optimal for generic costs when eps is small enough.
*/
int auction(const double *cost, int n, int *assign, double eps_final) {
    double *price = (double *)calloc(n, sizeof(double));
    int *owner = (int *)malloc(n * sizeof(int));
    int *queue = (int *)malloc(n * sizeof(int));
    int *nextq = (int *)malloc(n * sizeof(int));
    if (!price || !owner || !queue || !nextq) return 1;

    double cmax = 0.0;
    for (size_t i = 0; i < (size_t)n * n; i++) if (cost[i] > cmax) cmax = cost[i];
    double eps = cmax * 0.25;
    if (eps < eps_final) eps = eps_final;

    while (1) {
        for (int j = 0; j < n; j++) owner[j] = -1;
        int qn = n;
        for (int i = 0; i < n; i++) { queue[i] = i; assign[i] = -1; }
        int guard = 0;
        int limit = n * 40;
        int failed = 0;
        while (qn > 0) {
            if (++guard > limit) { failed = 1; break; }
            int nqn = 0;
            for (int qi = 0; qi < qn; qi++) {
                int i = queue[qi];
                const double *row = cost + (size_t)i * n;
                double best = -1e300, second = -1e300;
                int bestj = 0;
                for (int j = 0; j < n; j++) {
                    double val = -row[j] - price[j];
                    if (val > best) { second = best; best = val; bestj = j; }
                    else if (val > second) second = val;
                }
                double bid = price[bestj] + (best - second) + eps;
                int prev = owner[bestj];
                if (prev >= 0 && prev != i) {
                    assign[prev] = -1;
                    nextq[nqn++] = prev;
                }
                owner[bestj] = i;
                assign[i] = bestj;
                price[bestj] = bid;
            }
            for (int t = 0; t < nqn; t++) queue[t] = nextq[t];
            qn = nqn;
        }
        if (failed) { free(price); free(owner); free(queue); free(nextq); return 2; }
        if (eps <= eps_final) break;
        eps *= 0.25;
        if (eps < eps_final) eps = eps_final;
    }
    free(price); free(owner); free(queue); free(nextq);
    return 0;
}
