lib.auction_sparse.restype=ctypes.c_int

def recover(M):
    Csq = np.asarray(M, np.float64)**2
    n = Csq.shape[0]
    a = Csq.mean(1); b = Csq.mean(0); g = Csq.mean()
    rng = np.random.default_rng(0)
    Omega = rng.normal(size=(n, 6))
    ones = np.ones(n)
    GOmega = Csq@Omega - a[:,None]*(ones@Omega) - ones[:,None]*(b@Omega) + g*(ones@Omega)
    Q,_ = np.linalg.qr(GOmega, mode='reduced')
    Bsmall = Q.T@Csq - (Q.T@a)[:,None] - (Q.T@ones)[:,None]*b + g*(Q.T@ones)[:,None]
    U2,S,Vt = np.linalg.svd(Bsmall, full_matrices=False)
    U = Q@U2[:,:2]
    S2 = np.maximum(S[:2], 0)
    A = U*np.sqrt(S2)
    Bf = -Vt[:2].T * np.sqrt(S2)/2
    def res(p):
        w11=abs(p[0])+1e-10; w12=p[1]; w22=abs(p[2])+1e-10
        det=w11*w22-w12*w12
        if det<1e-12: return np.ones(2*n)*1e2
        s=p[3:5]
        W=np.array([[w11,w12],[w12,w22]])
        Winv=np.array([[w22,-w12],[-w12,w11]])/det
        ax=np.einsum('ij,jk,ik->i',A,W,A)
        by=np.einsum('ij,jk,ik->i',Bf,Winv,Bf)
        tnorm=float(s@Winv@s)
        out=np.empty(2*n)
        out[:n]=ax+by.mean()-2*(A@s)+tnorm-a
        out[n:]=by+ax.mean()+2*(Bf@(Winv@s))+tnorm-b
        return out
    p=np.array([1.,0,1.,0.,0.])
    for _ in range(8):
        r=res(p)
        if np.max(np.abs(r))<1e-8: break
        J=np.empty((r.size,5)); eps=1e-6; rp=p.copy()
        for kk in range(5):
            rp[kk]=p[kk]+eps; J[:,kk]=(res(rp)-r)/eps; rp[kk]=p[kk]
        step,*_=np.linalg.lstsq(J,-r,rcond=None)
        p=p+step
    w11=abs(p[0])+1e-10; w12=p[1]; w22=abs(p[2])+1e-10
    W=np.array([[w11,w12],[w12,w22]])
    L=np.linalg.cholesky(W)
