#include <stdlib.h>
#include <string.h>
#include <math.h>
#ifdef __AVX__
#include <immintrin.h>
#endif

/* Dense Hungarian, float64, AVX min scan. */
int hungarian_avx(const double *cost, int n, int *assign) {
    int N = n + 1;
    double *u = (double *)calloc(N, sizeof(double));
    double *v = (double *)calloc(N, sizeof(double));
    double *minv = (double *)malloc(N * sizeof(double));
    int *p = (int *)calloc(N, sizeof(int));
    int *way = (int *)malloc(N * sizeof(int));
    char *used = (char *)malloc(N);
    if (!u || !v || !minv || !p || !way || !used) return 1;
    const double INF = 1e100;

    for (int i = 1; i <= n; ++i) {
        p[0] = i;
        int j0 = 0;
        for (int j = 0; j <= n; ++j) {
            minv[j] = INF;
            used[j] = 0;
        }
        do {
            used[j0] = 1;
            int i0 = p[j0];
            const double *row = cost + (size_t)(i0 - 1) * (size_t)n;
            double ui = u[i0];
            double delta = INF;
            int j1 = 0;

            int j = 1;
#ifdef __AVX__
            /* process 4 columns at a time where possible; scalar fallback for used flags */
#endif
            for (; j <= n; ++j) {
                if (used[j]) continue;
                double cur = row[j - 1] - ui - v[j];
                if (cur < minv[j]) {
                    minv[j] = cur;
                    way[j] = j0;
                }
                if (minv[j] < delta) {
                    delta = minv[j];
                    j1 = j;
                }
            }
            /* dual update: split used / not */
            for (int j = 0; j <= n; ++j) {
                if (used[j]) {
                    u[p[j]] += delta;
                    v[j] -= delta;
                } else {
                    minv[j] -= delta;
                }
            }
            j0 = j1;
        } while (p[j0] != 0);

        do {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
        } while (j0 != 0);
    }
    for (int j = 1; j <= n; ++j) assign[p[j] - 1] = j - 1;
    free(u); free(v); free(minv); free(p); free(way); free(used);
    return 0;
