#include <stdlib.h>
#include <string.h>
#include <immintrin.h>

/* Hungarian with AVX2 inner loop.
   cost row-major n x n float64.
   v, minv, used are 1-indexed; we keep parallel 0-indexed arrays for SIMD.
*/
int hungarian_avx(const double *cost, int n, int *assign) {
    double *u = (double *)calloc(n + 1, sizeof(double));
    double *v = (double *)calloc(n + 1, sizeof(double));
    double *minv = (double *)malloc((n + 1) * sizeof(double));
    int *p = (int *)calloc(n + 1, sizeof(int));
    int *way = (int *)malloc((n + 1) * sizeof(int));
    /* 0-indexed scratch aligned */
    double *v0 = (double *)aligned_alloc(32, ((n + 7) & ~7) * sizeof(double));
    double *minv0 = (double *)aligned_alloc(32, ((n + 7) & ~7) * sizeof(double));
    int *way0 = (int *)aligned_alloc(32, ((n + 7) & ~7) * sizeof(int));
    char *used0 = (char *)aligned_alloc(32, ((n + 31) & ~31));
    if (!u || !v || !minv || !p || !way || !v0 || !minv0 || !way0 || !used0) return 1;

    const double INF = 1e100;
    int n4 = n & ~3;

    for (int i = 1; i <= n; ++i) {
        p[0] = i;
        int j0 = 0;
        for (int j = 0; j <= n; ++j) {
            minv[j] = INF;
            if (j) used0[j - 1] = 0;
        }
        used0[n] = 0; /* sentinel not used */
        for (int j = 0; j < n; ++j) {
            v0[j] = v[j + 1];
            minv0[j] = INF;
            way0[j] = 0;
        }
        for (int j = n; j < ((n + 7) & ~7); ++j) {
            v0[j] = 0;
            minv0[j] = INF;
            way0[j] = 0;
            used0[j] = 1; /* padding marked used so ignored */
        }

        do {
            if (j0 > 0) used0[j0 - 1] = 1;
            int i0 = p[j0];
            const double *row = cost + (size_t)(i0 - 1) * (size_t)n;
            double ui = u[i0];
            __m256d ui_v = _mm256_set1_pd(ui);

            int j = 0;
            for (; j < n4; j += 4) {
                /* skip if all 4 used */
                if (used0[j] & used0[j+1] & used0[j+2] & used0[j+3]) continue;
                __m256d c = _mm256_loadu_pd(row + j);
                __m256d vv = _mm256_loadu_pd(v0 + j);
                __m256d cur = _mm256_sub_pd(_mm256_sub_pd(c, ui_v), vv);
                __m256d mv = _mm256_loadu_pd(minv0 + j);
                __m256d cmp = _mm256_cmp_pd(cur, mv, _CMP_LT_OQ);
                int mask = _mm256_movemask_pd(cmp);
                if (mask) {
                    __m256d neu = _mm256_blendv_pd(mv, cur, cmp);
                    _mm256_storeu_pd(minv0 + j, neu);
                    if (mask & 1) way0[j] = j0;
                    if (mask & 2) way0[j+1] = j0;
                    if (mask & 4) way0[j+2] = j0;
                    if (mask & 8) way0[j+3] = j0;
                }
            }
            for (; j < n; ++j) {
                if (used0[j]) continue;
                double cur = row[j] - ui - v0[j];
                if (cur < minv0[j]) {
                    minv0[j] = cur;
                    way0[j] = j0;
                }
            }

            /* find min among unused */
            double delta = INF;
            int j1 = 0;
            for (int j = 0; j < n; ++j) {
                if (used0[j]) continue;
                if (minv0[j] < delta) {
                    delta = minv0[j];
                    j1 = j + 1;
                }
            }

            /* dual update */
            u[i0] += delta; /* p[j0] == i0, and j0 is used; but other used columns too */
            /* redo properly */
            /* undo the single add and do full */
            u[i0] -= delta;
            for (int j = 0; j <= n; ++j) {
                if (j == 0) {
                    if (j0 == 0) u[p[0]] += delta;
                    continue;
                }
                if (used0[j - 1]) {
                    u[p[j]] += delta;
                    v[j] -= delta;
                    v0[j - 1] -= delta;
                } else {
                    minv0[j - 1] -= delta;
                }
            }
            /* j0==0 case: p[0] is current free row, used0 doesn't cover j=0.
               The standard algorithm marks used[0]=1 always after first iteration start.
               We need used[0] semantics: column 0 is the dummy. */
            /* Fix: always update u[p[0]] and v[0] as "used" once we've started.
               Looking at standard code, used[0] is set when j0==0 at start, and
               u[p[0]] += delta, v[0] -= delta every iteration. */
            /* I handled j==0 only if j0==0 which is wrong after first step.
               Let's patch by always treating dummy column as used. */
            if (j0 != 0) {
                u[p[0]] += delta;
                v[0] -= delta;
            }
            j0 = j1;
            p[j0] = p[j0]; /* no-op keep compiler calm */
        } while (p[j0] != 0);

        /* augment, translating way0 (0-index columns) back.
           way[j] for j>=1 stored in way0[j-1]. way[0] unused. */
        for (int j = 1; j <= n; ++j) way[j] = way0[j - 1];
        do {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
        } while (j0 != 0);
    }
    for (int j = 1; j <= n; ++j) assign[p[j] - 1] = j - 1;
    free(u); free(v); free(minv); free(p); free(way);
    free(v0); free(minv0); free(way0); free(used0);
    return 0;
}
