{"command":"cat > lapmod.c << 'EOF'
/*
 * Jonker-Volgenant dense LAP (minimization), square, float64.
 * Based on the lapmod / lapjv algorithm structure from Jonker & Volgenant 1987.
 * This version follows the widely used "lap.h" logic closely.
 */
#include <stdlib.h>
#include <string.h>
#include <math.h>

#ifndef BIG
#define BIG 1.0e18
#endif

static inline double cost_at(const double *c, int n, int i, int j) {
    return c[(size_t)i * n + j];
}

int lapjv_solve(const double *cost, int n, int *rowsol) {
    int *colsol = (int *)malloc((size_t)n * sizeof(int));
    double *d = (double *)malloc((size_t)n * sizeof(double));
    int *pred = (int *)malloc((size_t)n * sizeof(int));
    int *freeunassigned = (int *)malloc((size_t)n * sizeof(int));
    double *v = (double *)calloc((size_t)n, sizeof(double));
    char *unique = (char *)malloc((size_t)n);
    int *scan = (int *)malloc((size_t)n * sizeof(int));
    char *in_scan = (char *)calloc((size_t)n, 1);
    if (!colsol || !d || !pred || !freeunassigned || !v || !unique || !scan || !in_scan) return -1;

    for (int i = 0; i < n; i++) {
        rowsol[i] = -1;
        colsol[i] = -1;
    }

    /* COLUMN REDUCTION */
    for (int j = n - 1; j >= 0; --j) {
        double minv = cost_at(cost, n, 0, j);
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double h = cost_at(cost, n, i, j);
            if (h < minv) { minv = h; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] == -1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            unique[j] = 0;
        }
    }

    /* REDUCTION TRANSFER */
    for (int i = 0; i < n; ++i) {
        if (rowsol[i] == -1) continue;
        int j1 = rowsol[i];
        double minv = BIG;
        for (int j = 0; j < n; ++j) {
            if (j == j1) continue;
            double h = cost_at(cost, n, i, j) - v[j];
            if (h < minv) minv = h;
        }
        v[j1] -= minv; /* wait, standard is v[j1] = cost - minv, and v was column min = cost of matched? */
        /* The matched edge reduced cost becomes minv? Let's use the classic formula:
           v[j1] = cost[i][j1] - min
           Since v[j1] was previously the column minimum, and row i achieved it,
           cost[i][j1] == old v[j1]. Setting v[j1] = cost - min = oldv - min
           is equivalent to v[j1] -= min. OK if row i is the one that set the column min.
           If another row had the same min, still cost[i][j1] == v[j1]. Good.
        */
    }

    /* AUGMENTING ROW REDUCTION */
    int nfree = 0;
    for (int f = 0; f < 2; ++f) {
        int k = 0;
        for (int i = 0; i < n; ++i) {
            if (rowsol[i] != -1) continue;
            double u1 = BIG, u2 = BIG;
            int j1 = -1, j2 = -1;
            for (int j = 0; j < n; ++j) {
                double h = cost_at(cost, n, i, j) - v[j];
                if (h < u2) {
                    if (h >= u1) {
                        u2 = h; j2 = j;
                    } else {
                        u2 = u1; u1 = h; j2 = j1; j1 = j;
                    }
                }
            }
            int i0 = colsol[j1];
            double vj1_new;
            if (u1 < u2) {
                v[j1] = v[j1] - (u2 - u1);
            } else if (i0 >= 0) {
                j1 = j2;
                i0 = colsol[j2];
            }
            if (i0 >= 0) {
                if (u1 < u2) {
                    freeunassigned[k++] = i0;
                    rowsol[i0] = -1;
                } else {
                    freeunassigned[k++] = i;
                    continue;
                }
            }
            rowsol[i] = j1;
            colsol[j1] = i;
        }
        nfree = k;
        /* second pass uses the free list implicitly by scanning rowsol == -1 */
    }

    /* rebuild free list */
    nfree = 0;
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) freeunassigned[nfree++] = i;

    /* AUGMENT */
    for (int f = 0; f < nfree; ++f) {
        int freerow = freeunassigned[f];
        for (int j = 0; j < n; ++j) {
            d[j] = cost_at(cost, n, freerow, j) - v[j];
            pred[j] = freerow;
            in_scan[j] = 0;
        }
        int low = 0, up = 0;
        double minv = d[0];
        for (int j = 1; j < n; ++j) if (d[j] < minv) minv = d[j];
        int endofpath = -1;
        for (int j = 0; j < n; ++j) {
            if (d[j] == minv) {
                if (colsol[j] < 0) { endofpath = j; break; }
                in_scan[j] = 1;
                scan[up++] = j;
            }
        }
        if (endofpath < 0) {
            for (;;) {
                if (low == up) {
                    double minv2 = BIG;
                    for (int j = 0; j < n; ++j) if (!in_scan[j] && d[j] < minv2) minv2 = d[j];
                    double delta = minv2 - minv;
                    for (int j = 0; j < n; ++j) {
                        if (in_scan[j]) {
                            int irow = colsol[j];
                            v[j] += delta;
                        } else {
                            d[j] -= delta;
                        }
                    }
                    minv = minv2;
                    for (int j = 0; j < n; ++j) {
                        if (!in_scan[j] && d[j] <= 0.0) {
                            if (colsol[j] < 0) { endofpath = j; break; }
                            in_scan[j] = 1;
                            scan[up++] = j;
                        }
                    }
                    if (endofpath >= 0) break;
                    continue;
                }
                int jcur = scan[low++];
                int irow = colsol[jcur];
                double cred_base = cost_at(cost, n, irow, jcur) - v[jcur];
                for (int j = 0; j < n; ++j) {
                    if (in_scan[j]) continue;
                    double h = cost_at(cost, n, irow, j) - v[j] - cred_base;
                    if (h < d[j]) {
                        d[j] = h;
                        pred[j] = irow;
                        if (h <= 0.0) {
                            if (colsol[j] < 0) { endofpath = j; break; }
                            in_scan[j] = 1;
                            scan[up++] = j;
                        }
                    }
                }
                if (endofpath >= 0) break;
            }
        }
        /* augment */
        int j = endofpath;
        for (;;) {
            int irow = pred[j];
            int nxt = rowsol[irow];
            colsol[j] = irow;
            rowsol[irow] = j;
            if (irow == freerow) break;
            j = nxt;
        }
    }

    free(colsol); free(d); free(pred); free(freeunassigned); free(v); free(unique); free(scan); free(in_scan);
    return 0;
}
