#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <omp.h>

/* Dense epsilon-scaling auction, OpenMP over rows within a bidding round.
   Bids are applied serially after the parallel value scan to avoid races,
   but the O(n^2) scan is parallel.
   To get more parallelism we bid in parallel on disjoint columns using a
   two-phase approach: each free row computes its best column in parallel,
   then we resolve conflicts serially (cheap).
*/
int auction_omp(const double *cost, int n, int *assign, double eps_final) {
    double *price = (double *)calloc(n, sizeof(double));
    int *owner = (int *)malloc(n * sizeof(int));
    int *queue = (int *)malloc(n * sizeof(int));
    int *nextq = (int *)malloc(n * sizeof(int));
    int *bestj = (int *)malloc(n * sizeof(int));
    double *bid = (double *)malloc(n * sizeof(double));
    if (!price || !owner || !queue || !nextq || !bestj || !bid) return 1;

    double cmax = 0.0;
    #pragma omp parallel for reduction(max:cmax)
    for (int i = 0; i < n; i++) {
        const double *row = cost + (size_t)i * n;
        double m = 0.0;
        for (int j = 0; j < n; j++) if (row[j] > m) m = row[j];
        if (m > cmax) cmax = m;
    }
    double eps = cmax * 0.25;
    if (eps < eps_final) eps = eps_final;

    while (1) {
        for (int j = 0; j < n; j++) owner[j] = -1;
        int qn = n;
        for (int i = 0; i < n; i++) { queue[i] = i; assign[i] = -1; }
        int guard = 0;
        int limit = n * 50;
        while (qn > 0) {
            if (++guard > limit) { 
                free(price); free(owner); free(queue); free(nextq); free(bestj); free(bid);
                return 2;
            }
            /* parallel best/second scan */
            #pragma omp parallel for schedule(static)
            for (int qi = 0; qi < qn; qi++) {
                int i = queue[qi];
                const double *row = cost + (size_t)i * n;
                double best = -1e300, second = -1e300;
                int bj = 0;
                for (int j = 0; j < n; j++) {
                    double val = -row[j] - price[j];
                    if (val > best) { second = best; best = val; bj = j; }
                    else if (val > second) second = val;
                }
                bestj[i] = bj;
                bid[i] = price[bj] + (best - second) + eps;
            }
            /* serial conflict resolution. If multiple rows want the same column,
               only the highest bid wins this round; losers stay queued.
               This is slightly different from sequential auction (which processes
               in order and later bids see updated prices) but epsilon-scaling
               still converges to optimal for small eps. */
            int nqn = 0;
            /* mark provisional winners: highest bid per column */
            /* reuse nextq as a winner row per column, -1 none; need a side array */
            /* We'll scan bidders and keep the best bid per column in a temp. */
            /* To avoid extra alloc, do two passes with owner as candidate winner
               and a bid-value stored by overwriting a scratch: use bid[] of winner. */
            int *col_winner = nextq; /* temporarily, size n, we'll rebuild queue after */
            double *col_bid = (double *)malloc(n * sizeof(double)); /* small, per round — bad */
            /* avoid malloc in loop: use assign array as scratch? assign is the output.
               Use a static-size approach: allocate once outside. We'll just do serial
               sequential update like the original, which is correct and the parallel
               scan already did the heavy work IF prices don't change within the round.
               Sequential update with stale prices (computed before any bid this round)
               is the Jacobi-style auction, still correct with epsilon. */
            free(col_bid);
            /* Jacobi: all bids computed from same prices. Apply highest bid per column. */
            for (int j = 0; j < n; j++) owner[j] = -2; /* -2 means no bidder this round; we'll restore */
            /* can't use owner that way because we need previous owners for unassignment.
               Keep previous owner in assign via current assign[]. */
            /* Determine winning bidder per column */
            /* col_best_bid and col_best_row allocated once — redo function structure.
               For this draft, serial apply in queue order using precomputed bids
               based on old prices. A later bidder for the same column may have a
               bid lower than an earlier one because both used old price. Take the max. */
            /* We'll store winning row in a local buffer allocated once. Break and fix below. */
            break;
        }
        break;
    }
    free(price); free(owner); free(queue); free(nextq); free(bestj); free(bid);
    return 3;
}
