} Chunk;

static void *chunk_worker(void *arg) {
    Chunk *c = (Chunk *)arg;
    double best = -1e300, second = -1e300;
    int bj = c->start;
    const double *row = c->row;
    const double *price = c->price;
    for (int j = c->start; j < c->end; j++) {
        double val = -row[j] - price[j];
        if (val > best) { second = best; best = val; bj = j; }
        else if (val > second) second = val;
    }
    c->best = best; c->second = second; c->bj = bj;
    return NULL;
}

int auction_mt(const double *cost, int n, int *assign, double eps_final) {
    double *price = (double *)calloc((size_t)n, sizeof(double));
    int *owner = (int *)malloc((size_t)n * sizeof(int));
    int *queue = (int *)malloc((size_t)n * sizeof(int));
    int *nextq = (int *)malloc((size_t)n * sizeof(int));
    if (!price || !owner || !queue || !nextq) return 1;

    double cmax = 0.0;
    for (size_t i = 0; i < (size_t)n * n; i++) if (cost[i] > cmax) cmax = cost[i];
    double eps = cmax * 0.25;
    if (eps < eps_final) eps = eps_final;

    pthread_t threads[NTHREADS];
    Chunk chunks[NTHREADS];
    int chunk = (n + NTHREADS - 1) / NTHREADS;

    while (1) {
        for (int j = 0; j < n; j++) owner[j] = -1;
        int qn = n;
        for (int i = 0; i < n; i++) { queue[i] = i; assign[i] = -1; }
        int guard = 0;
        int limit = n * 40;
        int failed = 0;
        while (qn > 0) {
            if (++guard > limit) { failed = 1; break; }
            int nqn = 0;
            for (int qi = 0; qi < qn; qi++) {
                int i = queue[qi];
                const double *row = cost + (size_t)i * n;
                for (int t = 0; t < NTHREADS; t++) {
                    chunks[t].row = row;
                    chunks[t].price = price;
                    chunks[t].n = n;
                    chunks[t].start = t * chunk;
                    chunks[t].end = (t + 1) * chunk;
                    if (chunks[t].start > n) chunks[t].start = n;
                    if (chunks[t].end > n) chunks[t].end = n;
                }
                for (int t = 0; t < NTHREADS; t++) pthread_create(&threads[t], NULL, chunk_worker, &chunks[t]);
                for (int t = 0; t < NTHREADS; t++) pthread_join(threads[t], NULL);
                double best = -1e300, second = -1e300;
                int bj = 0;
                for (int t = 0; t < NTHREADS; t++) {
                    if (chunks[t].start >= chunks[t].end) continue;
                    double b = chunks[t].best, s = chunks[t].second;
                    int tb = chunks[t].bj;
                    if (b > best) {
                        if (best > s) s = best;
                        second = s > second ? s : second;
                        /* second is max(old best, this second) if this best wins */
                        second = (best > s) ? best : s;
                        if (second < s && s < b) second = s;
                        best = b; bj = tb;
                        /* recompute second properly below */
                    }
                }
                /* recompute best and second from chunk results cleanly */
                best = -1e300; second = -1e300; bj = 0;
                for (int t = 0; t < NTHREADS; t++) {
                    if (chunks[t].start >= chunks[t].end) continue;
                    double b = chunks[t].best;
                    double s = chunks[t].second;
                    if (b > best) {
                        second = (best > s) ? best : s;
                        best = b;
                        bj = chunks[t].bj;
                    } else if (b > second) {
                        second = b;
                    }
                }
                double bid = price[bj] + (best - second) + eps;
                int prev = owner[bj];
                if (prev >= 0 && prev != i) {
                    assign[prev] = -1;
                    nextq[nqn++] = prev;
                }
                owner[bj] = i;
                assign[i] = bj;
                price[bj] = bid;
            }
            for (int t = 0; t < nqn; t++) queue[t] = nextq[t];
            qn = nqn;
        }
        if (failed) {
            free(price); free(owner); free(queue); free(nextq);
            return 2;
        }
        if (eps <= eps_final) break;
        eps *= 0.25;
        if (eps < eps_final) eps = eps_final;
    }
    free(price); free(owner); free(queue); free(nextq);
    return 0;
}
