#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define NTHREADS 4

typedef struct {
    const double *cost;
    const double *price;
    int n;
    int i;          /* row to scan, or -1 to exit */
    double best, second;
    int bj;
    pthread_mutex_t mu;
    pthread_cond_t cv_start, cv_done;
    int started;
    int done;
    int stop;
} Worker;

static void *worker_fn(void *arg) {
    Worker *w = (Worker *)arg;
    for (;;) {
        pthread_mutex_lock(&w->mu);
        while (!w->started && !w->stop) pthread_cond_wait(&w->cv_start, &w->mu);
        if (w->stop) { pthread_mutex_unlock(&w->mu); break; }
        int i = w->i;
        int n = w->n;
        const double *row = w->cost + (size_t)i * n;
        const double *price = w->price;
        w->started = 0;
        pthread_mutex_unlock(&w->mu);

        int start = 0, end = n; /* each worker scans a slice; slice set via i encoding? */
        /* We encode slice in i as negative? Better: use fields set before signal.
           Re-read start/end that we store in bj temporarily? Use dedicated via n split by thread id.
           Thread id is recovered from w - base, but we don't have it. Scan full assigned range
           stored by overwriting: we'll set a convention that cost pointer row is already the slice
           and n is the slice length, price is price+start. Then bj is local index.
        */
        double best = -1e300, second = -1e300;
        int bj = 0;
        for (int j = 0; j < n; j++) {
            double val = -row[j] - price[j];
            if (val > best) { second = best; best = val; bj = j; }
            else if (val > second) second = val;
        }
        pthread_mutex_lock(&w->mu);
        w->best = best; w->second = second; w->bj = bj;
        w->done = 1;
        pthread_cond_signal(&w->cv_done);
        pthread_mutex_unlock(&w->mu);
    }
    return NULL;
}

typedef struct {
    pthread_t th[NTHREADS];
    Worker w[NTHREADS];
    int inited;
} Pool;

static Pool pool;

static void pool_init(void) {
    if (pool.inited) return;
    for (int t = 0; t < NTHREADS; t++) {
        pthread_mutex_init(&pool.w[t].mu, NULL);
        pthread_cond_init(&pool.w[t].cv_start, NULL);
        pthread_cond_init(&pool.w[t].cv_done, NULL);
        pool.w[t].started = 0;
        pool.w[t].done = 0;
        pool.w[t].stop = 0;
        pthread_create(&pool.th[t], NULL, worker_fn, &pool.w[t]);
    }
    pool.inited = 1;
}

int auction_pool(const double *cost, int n, int *assign, double eps_final) {
    pool_init();
    double *price = (double *)calloc((size_t)n, sizeof(double));
    int *owner = (int *)malloc((size_t)n * sizeof(int));
