            if (++guard > limit) { failed = 1; break; }
            int nqn = 0;
            for (int qi = 0; qi < qn; qi++) {
                int i = queue[qi];
                const double *row = cost + (size_t)i * n;
                for (int t = 0; t < NTHREADS; t++) {
                    int s = t * slice;
                    int e = s + slice;
                    if (e > n) e = n;
                    if (s > n) s = n;
                    Worker *w = &pool.w[t];
                    pthread_mutex_lock(&w->mu);
                    w->cost = row + s;      /* slice of the row */
                    w->price = price + s;
                    w->n = e - s;
                    w->done = 0;
                    w->started = 1;
                    pthread_cond_signal(&w->cv_start);
                    pthread_mutex_unlock(&w->mu);
                }
                double best = -1e300, second = -1e300;
                int bj = 0;
                for (int t = 0; t < NTHREADS; t++) {
                    Worker *w = &pool.w[t];
                    pthread_mutex_lock(&w->mu);
                    while (!w->done) pthread_cond_wait(&w->cv_done, &w->mu);
                    int s = t * slice;
                    double b = w->best, sec = w->second;
                    int local = w->bj;
                    pthread_mutex_unlock(&w->mu);
                    if (w->n <= 0) continue;
                    int global = s + local;
                    if (b > best) {
                        second = (best > sec) ? best : sec;
                        best = b;
                        bj = global;
                    } else if (b > second) {
