#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define NTHREADS 4

typedef struct {
    const double *cost;
    const double *price;
    const int *rows;     /* row indices to process */
    int nrows;
    int n;
    int tid;
    int nthreads;
    double eps;
    int *bestj;          /* output indexed by row id */
    double *bidv;
} BatchJob;

static void *batch_worker(void *arg) {
    BatchJob *job = (BatchJob *)arg;
    int n = job->n;
    int start = (job->nrows * job->tid) / job->nthreads;
    int end = (job->nrows * (job->tid + 1)) / job->nthreads;
    const double *price = job->price;
    for (int qi = start; qi < end; qi++) {
        int i = job->rows[qi];
        const double *row = job->cost + (size_t)i * n;
        double best = -1e300, second = -1e300;
        int bj = 0;
        for (int j = 0; j < n; j++) {
            double val = -row[j] - price[j];
            if (val > best) { second = best; best = val; bj = j; }
            else if (val > second) second = val;
        }
        job->bestj[i] = bj;
        job->bidv[i] = price[bj] + (best - second) + job->eps;
    }
    return NULL;
}

/* Sequential auction but bids are computed in parallel batches of free rows
   using prices frozen at batch start. Within a batch, conflicts resolved by
   highest bid (Jacobi). Between batches, prices update, so it's a hybrid.
   For correctness of optimality with small eps, Jacobi auction is valid IF
   we don't reset prices between epsilon phases incorrectly and we run until
   all are assigned at each eps. The earlier Jacobi attempt failed because of
   a bug (perm false, negative cost diff meaning infeasible duplicate columns).
   Here we carefully keep a permutation: a column already assigned to someone
   NOT in this batch stays assigned; bidders only compete for columns, and if
   they steal an assigned column the previous owner is requeued.
*/
int auction_batch(const double *cost, int n, int *assign, double eps_final) {
    double *price = (double *)calloc((size_t)n, sizeof(double));
    int *owner = (int *)malloc((size_t)n * sizeof(int));
    int *queue = (int *)malloc((size_t)n * sizeof(int));
    int *nextq = (int *)malloc((size_t)n * sizeof(int));
    int *bestj = (int *)malloc((size_t)n * sizeof(int));
    double *bidv = (double *)malloc((size_t)n * sizeof(double));
    if (!price || !owner || !queue || !nextq || !bestj || !bidv) return 1;

    double cmax = 0.0;
    for (size_t i = 0; i < (size_t)n * n; i++) if (cost[i] > cmax) cmax = cost[i];
    double eps = cmax * 0.25;
    if (eps < eps_final) eps = eps_final;

    pthread_t threads[NTHREADS];
    BatchJob jobs[NTHREADS];
    const int BATCH = 32;

    while (1) {
        for (int j = 0; j < n; j++) owner[j] = -1;
        int qn = n;
        for (int i = 0; i < n; i++) { queue[i] = i; assign[i] = -1; }
        int guard = 0, limit = n * 60, failed = 0;
        while (qn > 0) {
            if (++guard > limit) { failed = 1; break; }
            int take = qn < BATCH ? qn : BATCH;
            for (int t = 0; t < NTHREADS; t++) {
                jobs[t].cost = cost;
                jobs[t].price = price;
                jobs[t].rows = queue;
                jobs[t].nrows = take;
                jobs[t].n = n;
                jobs[t].tid = t;
                jobs[t].nthreads = NTHREADS;
                jobs[t].eps = eps;
                jobs[t].bestj = bestj;
                jobs[t].bidv = bidv;
            }
            for (int t = 0; t < NTHREADS; t++) pthread_create(&threads[t], NULL, batch_worker, &jobs[t]);
            for (int t = 0; t < NTHREADS; t++) pthread_join(threads[t], NULL);

            /* apply bids in order of bid value descending so the best bidder for a column wins
               even though prices were frozen. Process the `take` bidders. */
            /* simple: apply in queue order, but bid was computed on old price, so the increment
               best-second is still a valid bid relative to old price. If two want same column,
               the later one in queue order overwrites if we apply sequentially with updated price
               checks. Safer: pick max bid per column among this batch. */
            /* We'll mark winners */
            int nqn = 0;
            /* first, determine winner per targeted column within batch */
            /* use a small map via scanning */
            for (int qi = 0; qi < take; qi++) {
                int i = queue[qi];
                int j = bestj[i];
                /* find if another earlier bidder in batch already claimed j with higher bid */
            }
            /* Apply Gauss-Seidel using precomputed (best, second) but recompute bid against
               CURRENT price so it's valid: bid = price[j] + (value_gap). The gap best-second
               was computed at old prices. If price[j] changed, gap may be stale.
               Fall back: just use the precomputed bidv which includes old price + gap + eps,
               and only accept if bidv > current price (else the row must rebid). */
            for (int qi = 0; qi < take; qi++) {
                int i = queue[qi];
                int j = bestj[i];
                double b = bidv[i];
                if (b > price[j] + 1e-15) {
                    int prev = owner[j];
                    if (prev >= 0 && prev != i) {
                        assign[prev] = -1;
                        nextq[nqn++] = prev;
                    }
                    owner[j] = i;
                    assign[i] = j;
                    price[j] = b;
                } else {
                    nextq[nqn++] = i;
                }
            }
            /* rows not taken this round stay queued */
            for (int qi = take; qi < qn; qi++) nextq[nqn++] = queue[qi];
            for (int t = 0; t < nqn; t++) queue[t] = nextq[t];
            qn = nqn;
        }
        if (failed) {
            free(price); free(owner); free(queue); free(nextq); free(bestj); free(bidv);
            return 2;
        }
        if (eps <= eps_final) break;
        eps *= 0.25;
        if (eps < eps_final) eps = eps_final;
    }
    free(price); free(owner); free(queue); free(nextq); free(bestj); free(bidv);
    return 0;
}
